<script lang="ts">
 import {onDestroy,untrack} from 'svelte';import {anyApi} from 'convex/server';import {auth} from '#lib/auth.svelte.ts';import {feed} from '#lib/feed.svelte.ts';import {pct} from '#lib/format.ts';
 let allowed=$state(false),checked=$state(false),index=$state<any>(null),date=$state(''),rows=$state<any[]>([]),loading=$state(false),error=$state(''),sport=$state('all'),outcome=$state('finished'),search=$state(''),shown=$state(50);let controller:AbortController|undefined;
 const today=()=>new Date(Date.now()+3600000).toISOString().slice(0,10),stamp=(n:number)=>new Date(n).toLocaleString('en-NG',{timeZone:'Africa/Lagos',dateStyle:'medium',timeStyle:'short'});
 const dates=$derived(Object.keys(index?.days??{}).sort().reverse());
 $effect(()=>{const client=auth.client;allowed=false;checked=!client;if(!client)return;return client.onUpdate(anyApi.admin.status,{},r=>{allowed=r?.isSuperAdmin===true;checked=true;},()=>{checked=true;error='Administrator access could not be verified.';});});
 $effect(()=>{const generation=feed.data?.generatedAt;if(allowed){generation;untrack(()=>void loadIndex());}else{controller?.abort();index=null;rows=[];}});onDestroy(()=>controller?.abort());
 async function json(response:Response){if(!response.ok)throw Error(`History request failed (HTTP ${response.status}).`);let bytes=new Uint8Array(await response.arrayBuffer());if(bytes[0]===31&&bytes[1]===139)bytes=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());if(bytes.length>64*1024*1024)throw Error('History exceeds the display budget.');return JSON.parse(new TextDecoder().decode(bytes));}
 async function loadIndex(){if(!allowed||loading)return;loading=true;error='';controller=new AbortController();try{const data=await json(await fetch('/api/admin/evidence',{credentials:'same-origin',signal:controller.signal}));if(!allowed)return;index=data.history??null;if(!date||!index?.days?.[date])date=Object.keys(index?.days??{}).sort().reverse().find(d=>d<=today())??Object.keys(index?.days??{}).sort()[0]??'';}catch(e){if((e as Error).name!=='AbortError')error=(e as Error).message;}finally{loading=false;}if(date&&allowed)await loadDay();}
 async function loadDay(){if(!allowed||!date||loading)return;controller?.abort();controller=new AbortController();loading=true;error='';rows=[];shown=50;try{const data=await json(await fetch(`/api/admin/evidence/history?date=${encodeURIComponent(date)}`,{credentials:'same-origin',signal:controller.signal}));if(!allowed)return;if(data.schema!==1||data.date!==date||!data.rows)throw Error('Unsupported history record.');rows=Object.values(data.rows);}catch(e){if((e as Error).name!=='AbortError')error=(e as Error).message;}finally{loading=false;}}
 const completed=$derived(rows.filter(r=>r.state==='finished'));
 const filtered=$derived(rows.filter(r=>r.kickoff<=Date.now()&&(sport==='all'||r.sport===sport)&&(outcome==='all'||(outcome==='finished'?r.state==='finished':r.result===outcome))&&(!search||`${r.matchTitle} ${r.league} ${r.country??''} ${r.selection}`.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>b.kickoff-a.kickoff||b.modelProb-a.modelProb));
 const label=(r:string)=>({won:'Win',lost:'Loss',push:'Stake returned','half-won':'Half win','half-lost':'Half loss',pending:'Awaiting result',ungraded:'Ungraded'}[r]??r);
</script>
<svelte:head><title>Evidence history — PuntersEdge administration</title><meta name="robots" content="noindex,nofollow" /></svelte:head>
<section class="min-w-0 space-y-5">
 <header class="surface p-5 sm:p-7"><p class="text-xs font-semibold uppercase tracking-widest text-model">📜 Recorded pre-match shortlist</p><h1 class="mt-3 text-3xl font-bold">Evidence history</h1><p class="mt-3 max-w-3xl text-sm leading-relaxed text-haze">Selections that met the published default evidence rules before kickoff. Final scores and verified outcomes update after results arrive; the original Model % and recurrence evidence remain frozen.</p><div class="mt-4 flex flex-wrap gap-3"><a class="btn-secondary" href="/admin/evidence">🌡️ Upcoming shortlist</a><button class="btn-secondary" onclick={loadIndex} disabled={!allowed||loading}>Refresh history</button></div></header>
 {#if error}<div class="surface border-loss/50 p-4" role="alert"><p>{error}</p><button class="btn-secondary mt-3" disabled={loading} onclick={loadIndex}>Retry</button></div>{/if}
 {#if !checked}<div class="workspace-state" role="status">Verifying administrator access…</div>{:else if !allowed}<div class="workspace-state"><h2>Administrator access required</h2><a class="btn-primary mt-3" href="/login?next=%2Fadmin%2Fevidence%2Fhistory">Sign in</a></div>{:else}
 <div class="surface p-4"><p class="text-sm text-haze">{#if index?.startedAt}Recording started {stamp(index.startedAt)} WAT.{:else}History will start with the next evidence refresh.{/if} Earlier completed games are not retrospectively labelled as shortlisted. History records default-rule qualification, rather than every administrator's temporary filter settings. Dates use Lagos time.</p></div>
 <div class="surface grid min-w-0 gap-3 p-4 sm:grid-cols-2 xl:grid-cols-4"><label class="grid gap-1 text-xs text-haze">Kickoff date<select class="control" bind:value={date} onchange={loadDay} disabled={loading||!dates.length}>{#each dates as d}<option value={d}>{d} · {index.days[d].completed} completed / {index.days[d].count} options</option>{/each}</select></label><label class="grid gap-1 text-xs text-haze">Sport<select class="control" bind:value={sport}><option value="all">All sports</option><option value="football">⚽ Football</option><option value="basketball">🏀 Basketball</option><option value="nba">🏀 NBA</option><option value="hockey">🏒 Hockey</option><option value="baseball">⚾ Baseball</option></select></label><label class="grid gap-1 text-xs text-haze">Outcome<select aria-label="Outcome" class="control" bind:value={outcome}><option value="finished">Completed matches</option><option value="won">Wins</option><option value="lost">Losses</option><option value="push">Stake returned</option><option value="ungraded">Ungraded</option><option value="pending">Awaiting result</option><option value="all">All started selections</option></select></label><label class="grid gap-1 text-xs text-haze">Fixture, league or selection<input class="control" type="search" bind:value={search} placeholder="Search recorded selections" /></label></div>
 <div class="grid grid-cols-2 gap-3 lg:grid-cols-4">{#each [['Completed options',completed.length],['Wins',completed.filter(r=>r.result==='won').length],['Losses',completed.filter(r=>r.result==='lost').length],['Shown by filters',filtered.length]] as [title,n]}<div class="surface p-4"><p class="text-xs text-haze">{title}</p><p class="mt-2 text-2xl font-bold">{n}</p></div>{/each}</div>
 {#if loading}<div class="workspace-state" role="status">Loading recorded history…</div>{:else if !filtered.length}<div class="workspace-state"><h2>No recorded selections match these filters</h2><p>Upcoming entries move into this view after kickoff. Completed results will appear after the scheduled pipeline updates. Missing or unsupported outcomes stay ungraded.</p></div>{:else}
 <div class="surface max-w-full overflow-hidden"><p class="p-4 text-xs text-haze">Swipe within the table on mobile. Counts refer to market options, so one fixture can have several independently graded selections.</p><div class="max-w-full overflow-x-auto overscroll-x-contain"><table><caption class="sr-only">Recorded shortlist selections and settled outcomes</caption><thead><tr><th>#</th><th>Fixture & competition</th><th>Recorded selection</th><th>Pre-match Model %</th><th>Evidence at qualification</th><th>Final score & outcome</th></tr></thead><tbody>{#each filtered.slice(0,shown) as r (r.id)}<tr data-sport={r.sport}><td>{filtered.indexOf(r)+1}</td><td><a class="fixture-name font-semibold hover:underline" href="/match?id={encodeURIComponent(r.fixtureId)}">{r.matchTitle}</a><p class="mt-2 text-xs text-haze">{r.league}{r.tournament&&r.tournament!==r.league?' · '+r.tournament:''}{r.country?' · '+r.country:''}</p><p class="mt-2 text-xs text-haze">{r.sport} · {stamp(r.kickoff)} WAT</p></td><td><strong>{r.selection}</strong><p class="mt-2 text-xs text-haze">{r.group}</p><p class="mt-2 text-xs text-haze">Published {stamp(r.publishedAt)}</p></td><td class="font-bold text-model">{pct(r.modelProb,1)}</td><td><strong>{pct(r.cohort.strikeRate,1)} strike</strong><p class="mt-2 text-xs text-haze">{r.cohort.won} wins / {r.cohort.binaryN} binary results</p><p class="mt-2 text-xs text-haze">{pct(r.cohort.interval.low,1)} historical floor</p></td><td><strong class="fixture-name">{r.score?`${r.score.home}–${r.score.away}`:'Score unavailable'}</strong>{#if r.score?.regHome!==undefined&&(r.score.regHome!==r.score.home||r.score.regAway!==r.score.away)}<p class="text-xs text-haze">Regulation {r.score.regHome}–{r.score.regAway}</p>{/if}<p class="mt-2 font-bold" class:text-model={r.result==='won'} class:text-loss={r.result==='lost'} class:text-book={!['won','lost'].includes(r.result)}>{label(r.result)}</p><p class="mt-1 text-xs text-haze">{r.state}</p></td></tr>{/each}</tbody></table></div>{#if filtered.length>shown}<div class="border-t border-line p-4"><button class="btn-secondary" onclick={()=>shown+=50}>Show 50 more · {filtered.length-shown} remaining</button></div>{/if}</div>{/if}
 {/if}
</section>
<style>
 .control{min-width:0;width:100%;min-height:44px;border:1px solid var(--color-line);border-radius:.75rem;padding:.65rem;background:var(--color-ink);color:var(--color-chalk);font-size:.875rem;}table{min-width:1050px;width:100%;font-size:.875rem;}th,td{text-align:left;vertical-align:top;padding:1rem;border-bottom:1px solid var(--color-line);}th{font-size:.7rem;text-transform:uppercase;color:var(--color-haze);}td:nth-child(2){min-width:230px;}td:nth-child(3){min-width:230px;}tr[data-sport="football"] td:first-child{border-left:4px solid #86efac;}tr[data-sport="hockey"] td:first-child{border-left:4px solid #7dd3fc;}tr[data-sport="basketball"] td:first-child,tr[data-sport="nba"] td:first-child{border-left:4px solid #fcd34d;}tbody tr:hover{background:color-mix(in srgb,var(--color-model) 5%,transparent);}
</style>
